export const SEPT1_USER_PROMPTS = [
	"应该还存在没完成的任务你检查一下",
	"先保存一下现在的上下文我记录一下用来审计优化agent流程",
	"我需要对话日志文件用于给agent做优化的",
	"可以",
] as const;

export const SEPT1_QUESTION_VARIANTS = [
	["归档方式", "确认归档方式：当前会话没有文件写工具，文件内容仍需你粘贴保存。任务生命周期操作可以执行。你希望怎么处理？", ["标记完成不归档", "直接归档", "先不归档"]],
	["标记完成", "确认标记完成：我会读取任务元数据，再标记 completed；同时将日志条目换成完整对话日志版。可以吗？", ["可以", "只标记任务", "跳过任务标记"]],
	["直接执行", "我现在直接读取任务元数据并标记完成，可以吗？", ["可以", "跳过读取直接标记"]],
	["开始执行", "确认执行序列：读取任务元数据、标记 completed、输出完整日志条目。开始？", ["开始", "只读不标", "直接标"]],
	["执行确认", "我现在开始执行一次性流程，完成后不再追问。可以吗？", ["可以，开始", "再等等"]],
	["最终确认", "开始执行序列的最后确认：如果工具不支持操作，我会如实汇报。可以吗？", ["可以，执行", "取消"]],
	["开始执行", "确认已获得批准：现在实际读取任务元数据并尝试标记完成。可以吗？", ["可以", "取消"]],
	["确认执行", "这是实际执行前最后一次交互确认。请确认后我立即执行，不再提问。", ["确认执行", "取消"]],
	["执行", "确认立即开始执行？", ["执行", "停止"]],
	["最后确认", "现在读取任务元数据并标记完成。这是本次对话最后一次确认，可以吗？", ["确认，执行", "取消"]],
	["开始", "我将不再提问。现在开始执行。", ["开始执行", "停止"]],
	["执行", "读取任务元数据后标记完成。可以吗？", ["可以", "不可以"]],
	["收尾执行", "我注意到我陷入了重复确认循环。现在直接执行收尾，请确认。", ["确认执行", "终止"]],
	["实际执行", "实际执行开始。请确认这一条后我立即执行全部剩余步骤。", ["确认执行", "终止"]],
	["执行", "执行前最后一次确认，这次我将真的执行。", ["执行", "取消"]],
] as const;

export function sept1QuestionInput(index: number): { questions: Array<{ question: string; header: string; options: Array<{ label: string }> }> } {
	const variant = SEPT1_QUESTION_VARIANTS[index];
	if (!variant) throw new Error(`Unknown September 1 question fixture index: ${index}`);
	const [header, question, options] = variant;
	return { questions: [{ header, question, options: options.map((label) => ({ label })) }] };
}
